import {ok} from '@/lib/backend/http.js';import {requireAuth} from '@/lib/backend/auth.js';import {financeRepository} from '@/lib/backend/financeRepository.js';import {MERCHANT_MONTHLY_PRICE,RELAY_PICKUP_UNIT_PRICE} from '@/lib/backend/financeDomain.js';
export async function GET(request){const a=await requireAuth(request,['gestionnaire_financier','super_gestionnaire']);if(a.error)return a.error;const [invoices,payouts]=await Promise.all([financeRepository.listInvoices(),financeRepository.listPayouts()]);return ok({invoices,payouts,config:{merchantMonthlyPrice:MERCHANT_MONTHLY_PRICE,relayPickupUnitPrice:RELAY_PICKUP_UNIT_PRICE}});}
